// 下は青、上は赤。高さ（@P.y）を 0〜1 に直してから色に使う
float t = fit(@P.y, -1, 1, 0, 1);
@Cd = set(t, 0.25, 1 - t);

// noise() は 0.06〜0.92 ほどの値を返す（実験135）。0.5 を引いて上下に振る
float n = noise(@P * 1.5);
@P.y += (n - 0.5) * 1.2;
@Cd = set(n, n, 1);

// rand() は点の番号から 0〜1 の決まった乱数を作る（毎回同じ）
@pscale = fit01(rand(@ptnum), 0.2, 1.0);
@Cd = set(rand(@ptnum + 7), 0.6, 0.3);

// 面ごとに走らせ、4 割ほどの面を消す。最後の 1 は、使われなくなった点も消す指定
if (rand(@primnum) < 0.4)
    removeprim(0, @primnum, 1);

// Detail は全体で 1 回だけ走る。ここで for ループを回して点を作り、前の点と線でつなぐ
int prev = -1;
for (int i = 0; i < 300; i++) {
    float t = i / 299.0;
    vector p = set(cos(t * 25) * t, t * 2, sin(t * 25) * t);
    int pt = addpoint(0, p);
    if (prev >= 0)
        addprim(0, "polyline", prev, pt);
    prev = pt;
}

// 2 つめの入力（番号 1）につないだドーナツの面までの距離
float d = xyzdist(1, @P);
@Cd = lerp({1, 0.45, 0.1}, {0.1, 0.2, 0.45}, fit(d, 0, 1.2, 0, 1));
